describe('PayPal Payment Method Selection', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully select PayPal as payment method', () => {
    // Verify checkout page loads
    cy.get('[data-testid="checkout-page"]').should('be.visible');
    cy.get('[data-testid="payment-method-options"]').should('be.visible');

    // Verify PayPal option is visible
    cy.get('[data-testid="paypal-option"]').should('be.visible');
    cy.get('[data-testid="paypal-option"]').should('contain', 'PayPal');

    // Select PayPal option
    cy.get('[data-testid="paypal-option"]').click();

    // Verify PayPal is selected
    cy.get('[data-testid="paypal-option"]').should('have.class', 'selected');
    cy.get('[data-testid="payment-method-label"]').should('contain', 'PayPal');

    // Verify PayPal specific fields appear (e.g., redirect button)
    cy.get('[data-testid="paypal-redirect-button"]').should('be.visible');
    cy.get('[data-testid="paypal-redirect-button"]').should('contain', 'Pay with PayPal');

    // Click to proceed to PayPal
    cy.get('[data-testid="paypal-redirect-button"]').click();

    // Verify redirect to PayPal is initiated
    cy.url().should('include', 'paypal.com');
    cy.get('[data-testid="paypal-login-form"]').should('be.visible');
  });

  it('should handle PayPal option being disabled or unavailable', () => {
    // Intercept API call to simulate PayPal being unavailable
    cy.intercept('POST', '/api/payment/paypal/validate', {
      statusCode: 503,
      body: { error: 'Service unavailable' }
    }).as('paypalValidation');

    // Navigate to checkout
    cy.visit('/checkout');

    // Verify PayPal option is visible initially
    cy.get('[data-testid="paypal-option"]').should('be.visible');

    // Attempt to select PayPal
    cy.get('[data-testid="paypal-option"]').click();

    // Wait for validation
    cy.wait('@paypalValidation');

    // Verify error message is displayed
    cy.get('[data-testid="paypal-error-message"]').should('be.visible');
    cy.get('[data-testid="paypal-error-message"]').should('contain', 'Service unavailable');

    // Verify PayPal option is not selected
    cy.get('[data-testid="paypal-option"]').should('not.have.class', 'selected');

    // Verify user can still select other payment methods
    cy.get('[data-testid="credit-card-option"]').should('be.visible');
    cy.get('[data-testid="credit-card-option"]').click();
    cy.get('[data-testid="credit-card-option"]').should('have.class', 'selected');
  });
});
